args.content:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    line-height: 1.6;
    color: #333;
    max-width: 900px;
    margin: 0 auto;
    padding: 20px;
    background: #fafafa;
}

header {
    text-align: center;
    padding: 40px 0;
    border-bottom: 3px solid #2c5f7c;
    margin-bottom: 30px;
}

h1 {
    font-size: 2.5em;
    color: #2c5f7c;
    margin-bottom: 10px;
}

.tagline {
    font-size: 1.2em;
    color: #666;
    font-style: italic;
}

nav {
    display: flex;
    justify-content: center;
    gap: 30px;
    margin-bottom: 40px;
    padding: 15px 0;
    border-bottom: 1px solid #ddd;
}

nav a {
    color: #2c5f7c;
    text-decoration: none;
    font-weight: 500;
    transition: color 0.2s;
}

nav a:hover {
    color: #1a3a4d;
    text-decoration: underline;
}

main {
    background: white;
    padding: 40px;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

section {
    margin-bottom: 50px;
}

h2 {
    color: #2c5f7c;
    font-size: 1.8em;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 2px solid #e0e0e0;
}

h3 {
    color: #333;
    font-size: 1.3em;
    margin: 20px 0 10px 0;
}

.offering {
    margin: 30px 0;
    padding: 20px;
    background: #f8f9fa;
    border-left: 4px solid #2c5f7c;
    border-radius: 4px;
}

.button {
    display: inline-block;
    margin-top: 10px;
    padding: 8px 16px;
    background: #2c5f7c;
    color: white;
    text-decoration: none;
    border-radius: 4px;
    transition: background 0.2s;
}

.button:hover {
    background: #1a3a4d;
}

.preview {
    margin: 25px 0;
    padding: 20px;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    background: #fafafa;
}

.preview h3 a {
    color: #2c5f7c;
    text-decoration: none;
}

.preview h3 a:hover {
    text-decoration: underline;
}

ul {
    margin-left: 20px;
}

li {
    margin: 10px 0;
}

footer {
    margin-top: 50px;
    padding-top: 20px;
    border-top: 1px solid #ddd;
    text-align: center;
    color: #666;
    font-size: 0.9em;
}

footer a {
    color: #2c5f7c;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
}

th, td {
    padding: 12px;
    text-align: left;
    border-bottom: 1px solid #ddd;
}

th {
    background: #2c5f7c;
    color: white;
    font-weight: 600;
}

tr:hover {
    background: #f8f9fa;
}

.intro {
    font-size: 1.1em;
    line-height: 1.8;
}

.principles ul {
    list-style: none;
    margin-left: 0;
}

.principles li {
    padding: 10px 0;
    border-bottom: 1px solid #f0f0f0;
}

code {
    background: #f4f4f4;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: 'Courier New', monospace;
    font-size: 0.9em;
}

.resource-card {
    margin: 20px 0;
    padding: 20px;
    background: #f8f9fa;
    border-radius: 4px;
    border-left: 4px solid #2c5f7c;
}

.resource-card h4 {
    color: #2c5f7c;
    margin-bottom: 10px;
}

.tag {
    display: inline-block;
    padding: 4px 10px;
    margin: 5px 5px 5px 0;
    background: #e0e0e0;
    border-radius: 3px;
    font-size: 0.85em;
    color: #555;
}
